const input=$json.body??$json;
const classification=String(input.classification??'').toLowerCase();
const dealId=input.deal_id??input.dealId,leadId=input.lead_id??input.leadId,propertyId=input.property_id??input.propertyId;
const baseMao=Number(input.mao??input.base_mao??0);
const sellerAsk=Number(input.seller_ask??input.counteroffer_amount??0);
const dnc=Boolean(input.dnc||input.do_not_contact||input.opted_out);
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const sourceKey=input.classification_idempotency_key??input.idempotency_key;
const valid=Boolean(dealId&&leadId&&propertyId&&sourceKey);
let factor=1,strategy='continue_negotiation',route='WF-365',reason='Continue negotiation using the current protected MAO.';
if(classification==='counteroffer'&&baseMao>0&&sellerAsk>0){
 const ratio=sellerAsk/baseMao;
 if(ratio<=1.02){factor=1.02;strategy='evaluate_near_mao_counter';reason='Counteroffer is at or near MAO; allow a tightly bounded tactical adjustment.'}
 else if(ratio<=1.15){factor=1.0;strategy='hold_mao';reason='Counteroffer is above MAO but within the evaluation band; protect current MAO.'}
 else {factor=.97;strategy='reduce_exposure';reason='Counteroffer is materially above MAO; reduce exposure and protect walk-away economics.'}
}else if(classification==='positive'){strategy='prepare_acceptance_or_contract';reason='Positive seller response; evaluate acceptance and contract readiness against protected MAO.'}
else if(classification==='rejection'){strategy='reengage';route='WF-345';reason='Seller rejected the current position; route to controlled re-engagement.'}
else if(classification==='opt_out'){strategy='stop';route='WF-126';reason='Seller opted out; automated communication must stop.'}
else if(classification==='question'||classification==='call_request'){strategy='respond_and_continue';reason='Seller needs clarification or a call; continue negotiation with protected economics.'}
else if(!classification){strategy='reconcile';route='WF-360';reason='Missing AI classification; reconcile upstream event.'}
const adjustedMao=baseMao>0?Math.round(baseMao*factor*100)/100:0;
const protectedMao=baseMao>0?Math.min(adjustedMao,baseMao*1.02):0;
if(dnc){strategy='stop';route='WF-126';reason='DNC/opt-out state overrides negotiation automation.'}
else if(blockers.length){strategy='blocked';route='WF-126';reason='Operational blockers require controlled human handling.'}
else if(!valid&&route!=='WF-126'){strategy='reconcile';route='WF-360';reason='Required identity/idempotency fields are missing.'}
const decisionKey=sourceKey?\`${sourceKey}:strategy:${strategy}:mao:${protectedMao}\`:null;
return [{json:{workflow:'WF-371',classification,strategy,route,reason,deal_id:dealId,lead_id:leadId,property_id:propertyId,base_mao:baseMao,seller_ask:sellerAsk,adjustment_factor:factor,adjusted_mao:adjustedMao,protected_mao:protectedMao,mao_protected:baseMao>0&&protectedMao<=baseMao*1.02,dnc,blockers,source_classification_key:sourceKey,decision_idempotency_key:decisionKey,identity_valid:valid,next_action:route==='WF-365'?'revised_offer_or_walkaway_decision':route==='WF-345'?'controlled_reengagement':route==='WF-126'?'human_control':'reconcile_upstream_classification',audit_event:'negotiation_strategy_dynamic_mao_evaluation'}}];
